insert into public.jarvis_memory (id, user_id, kind, strength, text, serves, track, target, category, course, source) values
  ('9a1f0c2e-0001-4b6a-9c11-5a1a00000001', '5ab604e4-1ddb-499f-a675-e15de3093b66', 'goal', null, 'Get to 80 kg at 12% body fat, as fast as possible.', '{}', 'body', '{"weightKg":80,"bodyFatPct":12,"by":"asap"}'::jsonb, null, null, 'setup'),
  ('9a1f0c2e-0002-4b6a-9c11-5a1a00000002', '5ab604e4-1ddb-499f-a675-e15de3093b66', 'goal', null, 'Get the highest grade possible this semester.', '{}', 'grades', '{"term":"Fall 2026"}'::jsonb, null, null, 'setup'),
  ('9a1f0c2e-0101-4b6a-9c11-5a1a00000101', '5ab604e4-1ddb-499f-a675-e15de3093b66', 'habit', 'must', 'Go to the gym every day. Rest days are rare and random — I pick them myself (sometimes one a week, sometimes one a month). When PPL Coach shows Rest, I carry on with Push.', '{9a1f0c2e-0001-4b6a-9c11-5a1a00000001}', 'gym_daily', null, null, null, 'setup'),
  ('9a1f0c2e-0102-4b6a-9c11-5a1a00000102', '5ab604e4-1ddb-499f-a675-e15de3093b66', 'habit', 'must', 'Train right: progressive overload.', '{9a1f0c2e-0001-4b6a-9c11-5a1a00000001}', 'progressive_overload', null, null, null, 'setup'),
  ('9a1f0c2e-0103-4b6a-9c11-5a1a00000103', '5ab604e4-1ddb-499f-a675-e15de3093b66', 'habit', 'must', 'Eat the correct macros for each phase.', '{9a1f0c2e-0001-4b6a-9c11-5a1a00000001}', 'macros', null, null, null, 'setup'),
  ('9a1f0c2e-0104-4b6a-9c11-5a1a00000104', '5ab604e4-1ddb-499f-a675-e15de3093b66', 'habit', 'must', 'Go to classes on time.', '{9a1f0c2e-0002-4b6a-9c11-5a1a00000002}', 'classes_on_time', null, null, null, 'setup'),
  ('9a1f0c2e-0105-4b6a-9c11-5a1a00000105', '5ab604e4-1ddb-499f-a675-e15de3093b66', 'habit', 'must', 'Do my assignments on time.', '{9a1f0c2e-0002-4b6a-9c11-5a1a00000002}', 'assignments_on_time', null, null, null, 'setup'),
  ('9a1f0c2e-0106-4b6a-9c11-5a1a00000106', '5ab604e4-1ddb-499f-a675-e15de3093b66', 'habit', 'must', 'Study for tests and exams on time.', '{9a1f0c2e-0002-4b6a-9c11-5a1a00000002}', 'study_on_time', null, null, null, 'setup'),
  ('9a1f0c2e-0201-4b6a-9c11-5a1a00000201', '5ab604e4-1ddb-499f-a675-e15de3093b66', 'rule', 'prefer', 'I sleep from 9pm to 5am.', '{}', null, null, 'sleep', null, 'setup'),
  ('9a1f0c2e-0202-4b6a-9c11-5a1a00000202', '5ab604e4-1ddb-499f-a675-e15de3093b66', 'rule', 'prefer', 'Gym at 6pm if possible.', '{9a1f0c2e-0001-4b6a-9c11-5a1a00000001}', null, null, 'gym', null, 'setup'),
  ('9a1f0c2e-0203-4b6a-9c11-5a1a00000203', '5ab604e4-1ddb-499f-a675-e15de3093b66', 'rule', 'prefer', 'An assignment takes me about 1 hour (2 hours max). Studying for a test or GCA takes 2–4 hours. An exam takes 4–10 hours spread over a few days.', '{9a1f0c2e-0002-4b6a-9c11-5a1a00000002}', null, null, 'study', null, 'setup'),
  ('9a1f0c2e-0204-4b6a-9c11-5a1a00000204', '5ab604e4-1ddb-499f-a675-e15de3093b66', 'rule', 'prefer', 'Preparing for a graded lab takes me about 30 minutes, sometimes none.', '{9a1f0c2e-0002-4b6a-9c11-5a1a00000002}', null, null, 'study', null, 'setup'),
  ('9a1f0c2e-0205-4b6a-9c11-5a1a00000205', '5ab604e4-1ddb-499f-a675-e15de3093b66', 'rule', 'prefer', 'I do assignments as soon as they open.', '{9a1f0c2e-0002-4b6a-9c11-5a1a00000002}', null, null, 'study', null, 'setup'),
  ('9a1f0c2e-0206-4b6a-9c11-5a1a00000206', '5ab604e4-1ddb-499f-a675-e15de3093b66', 'rule', 'must', 'I need a 1-hour study block the day before every GCA.', '{9a1f0c2e-0002-4b6a-9c11-5a1a00000002}', null, null, 'study', null, 'setup'),
  ('9a1f0c2e-0207-4b6a-9c11-5a1a00000207', '5ab604e4-1ddb-499f-a675-e15de3093b66', 'rule', 'prefer', 'My maid can cook for me between 6am and 9pm: I text her what I want and when I want it by. Sometimes I like to cook myself, like breakfast. She or I can cook the next day’s meals ahead if needed.', '{9a1f0c2e-0001-4b6a-9c11-5a1a00000001}', null, null, 'food', null, 'setup'),
  ('9a1f0c2e-0209-4b6a-9c11-5a1a00000209', '5ab604e4-1ddb-499f-a675-e15de3093b66', 'rule', 'must', 'CE 400 (Grad Project I, Dr. Mutaz Al-Tarawneh): reports go through Turnitin in APA style; a late submission loses 40% within 24 hours and 60% within 48 hours, then it is a zero; attendance is 5% of the grade; the syllabus expects about 15 hours a week of project work outside class.', '{9a1f0c2e-0002-4b6a-9c11-5a1a00000002}', null, null, 'university', 'CE 400', 'setup'),
  ('9a1f0c2e-0210-4b6a-9c11-5a1a00000210', '5ab604e4-1ddb-499f-a675-e15de3093b66', 'rule', 'prefer', 'I have one home. My grandmother’s home is closer to the university but has none of my things there.', '{9a1f0c2e-0002-4b6a-9c11-5a1a00000002}', null, null, 'home', null, 'setup'),
  ('9a1f0c2e-0211-4b6a-9c11-5a1a00000211', '5ab604e4-1ddb-499f-a675-e15de3093b66', 'rule', 'prefer', 'My gym membership covers several Oxygen Gym branches — Rigae, Mahboula and Sabah Al-Salem. Pick the branch for each session, at the emptiest time if possible.', '{9a1f0c2e-0001-4b6a-9c11-5a1a00000001}', null, null, 'gym', null, 'setup'),
  ('9a1f0c2e-0212-4b6a-9c11-5a1a00000212', '5ab604e4-1ddb-499f-a675-e15de3093b66', 'rule', 'prefer', 'Oxygen Gym is at its busiest from 2pm to 9pm; before 2pm is quieter. Weigh this against my 6pm preference, classes and bedtime with common sense.', '{9a1f0c2e-0001-4b6a-9c11-5a1a00000001}', null, null, 'gym', null, 'setup'),
  ('9a1f0c2e-0208-4b6a-9c11-5a1a00000208', '5ab604e4-1ddb-499f-a675-e15de3093b66', 'rule', 'must', 'Never be late. When traffic or time forces changes, protect in this order: university first, then gym, then nutrition, then sleep.', '{9a1f0c2e-0002-4b6a-9c11-5a1a00000002,9a1f0c2e-0001-4b6a-9c11-5a1a00000001}', null, null, 'travel', null, 'setup')
